INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0368', '忍者と殺し屋のふたりぐらし', '2025年春', 'PR0127', 'TVシリーズ', 12, '『忍者と殺し屋のふたりぐらし』（にんじゃところしやのふたりぐらし）は、ハンバーガーによる日本の漫画作品。『コミック電撃だいおうじ』（KADOKAWA）にてVol.90（2021年2月26日発売）から連載中。略称は『にんころ』。 メディアミックスとして、テレビアニメが2025年4月から6月まで放送された。', 177120) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0369', 'ある魔女が死ぬまで', '2025年春', 'PR0060', 'TVシリーズ', 12, '『ある魔女が死ぬまで』（あるまじょがしぬまで）は、坂による日本のライトノベル。イラストはコレフジが担当している。元々は小説投稿サイト「カクヨム」にて2019年10月から2022年8月まで連載された投稿作品で、Web版の方は物語が完結している。2021年12月から2025年9月まで電撃の新文芸（KADOKAWA）から書籍版が刊行された。電撃の新文芸2周年記念コンテスト〈熱い師弟関係〉部門大賞を受賞し', 178701) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0370', 'mono', '2025年春', 'PR0128', 'TVシリーズ', 12, NULL, 176246) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0371', 'ゴリラの神から加護された令嬢は王立騎士団で可愛がられる', '2025年春', 'PR0129', 'TVシリーズ', 12, '『ゴリラの神から加護された令嬢は王立騎士団で可愛がられる』（ゴリラのかみからかごされたれいじょうはおうりつきしだんでかわいがられる）は、シロヒによる日本のライトノベル。小説投稿サイト「小説家になろう」にて、2020年8月10日から2021年8月23日まで連載されたオンライン小説で、書籍化はされていないがライトノベルとして認知されている。当初のタイトルは『ゴリラの神から加護されたお嬢様の気持ち考えた', 182060) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0372', '日々は過ぎれど飯うまし', '2025年春', 'PR0083', 'TVシリーズ', 12, '『日々は過ぎれど飯うまし』（ひびはすぎれどめしうまし）は、P.A.WORKS制作による日本のオリジナルテレビアニメ。2025年4月から6月までTOKYO MXほかにて放送された。略称は「ひびめし」。東京都八王子市が物語の舞台。', 185939) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN0373', '小市民シリーズ 第2期', '2025年春', 'PR0079', 'TVシリーズ', 12, NULL, 181182) ON CONFLICT DO NOTHING;
