INSERT INTO characters (character_id, anime_id, name, description, age, gender, anilist_id) VALUES ('CH002958', 'AN0683', 'ユウ', 'Aki and the others helped her when she was surrounded by zombies. She is very knowledgeable.', NULL, 'Female', 296834) ON CONFLICT DO NOTHING;
